<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');$db=Database::connection();$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'';if($action==='add'){$code=strtoupper(trim($_POST['code']));$name=trim($_POST['name']);$category=$_POST['category'];if(!preg_match('/^[A-Z0-9_]{3,50}$/',$code)||$name==='')throw new InvalidArgumentException('Valid code and name are required.');if(!in_array($category,['electricity','internet','cable','airtime','data','water','other'],true))throw new InvalidArgumentException('Invalid category.');$db->prepare('INSERT INTO billers(code,name,category,status) VALUES(?,?,?,"active")')->execute([$code,$name,$category]);$success='Biller added.';}elseif($action==='status'){$status=$_POST['status']==='active'?'active':'inactive';$db->prepare('UPDATE billers SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$success='Biller status updated.';}}catch(Throwable $e){$error=$e->getMessage();}}$billers=$db->query('SELECT b.*,COUNT(bp.id) payments,COALESCE(SUM(CASE WHEN bp.status="completed" THEN bp.amount ELSE 0 END),0) volume FROM billers b LEFT JOIN bill_payments bp ON bp.biller_id=b.id GROUP BY b.id ORDER BY b.category,b.name')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billers</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>Payment Biller Catalogue</h2><a href="/commserve/public/admin/">Dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm"><div class="card-body"><h5>Add Biller</h5><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="col-12"><label class="form-label">Code</label><input name="code" class="form-control" placeholder="COMM_WATER" required></div><div class="col-12"><label class="form-label">Name</label><input name="name" class="form-control" required></div><div class="col-12"><label class="form-label">Category</label><select name="category" class="form-select"><?php foreach(['electricity','internet','cable','airtime','data','water','other'] as $c):?><option value="<?=$c?>"><?=ucfirst($c)?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-primary w-100">Add Biller</button></div></form></div></div></div><div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Code</th><th>Name</th><th>Category</th><th>Status</th><th>Payments</th><th>Volume</th><th></th></tr></thead><tbody><?php foreach($billers as $b):?><tr><td class="font-monospace small"><?=e($b['code'])?></td><td><?=e($b['name'])?></td><td><?=e($b['category'])?></td><td><span class="badge text-bg-<?=$b['status']==='active'?'success':'secondary'?>"><?=e($b['status'])?></span></td><td><?=e((string)$b['payments'])?></td><td>₦<?=number_format((float)$b['volume'],2)?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$b['id']?>"><input type="hidden" name="status" value="<?=$b['status']==='active'?'inactive':'active'?>"><button class="btn btn-sm btn-outline-secondary"><?=$b['status']==='active'?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></body></html>
